Update Work Order.code:
// Update fields on an existing work order.
update({
  // MBO resource with the WORKORDERID, relative to baseUrl.
  endpoint: `maxrest/rest/mbo/workorder/${$.data.workOrderId}`,
  // Only the fields to change.
  body: {
    STATUS: 'COMP',
    DESCRIPTION: $.data.description,
  },
});

Update Asset.code:
// Update an asset by ASSETID.
update({
  endpoint: `maxrest/rest/mbo/asset/${$.data.assetId}`,
  body: {
    STATUS: $.data.status, // e.g. OPERATING, DECOMMISSIONED
    LOCATION: $.data.location,
  },
});

Update Inventory Balances (7.5).code:
// Post a physical count to inventory balances (Maximo 7.5).
update75({
  endpoint: 'maxrest/rest/mbo/invbalances',
  body: {
    ITEMNUM: $.data.itemNum,
    LOCATION: $.data.storeroom,
    SITEID: $.data.siteId,
    PHYSCNT: $.data.countedQuantity,
  },
});

Fetch Inventory Item.code:
// Look up an item's inventory and forward the result.
fetch({
  // Object structure path, relative to baseUrl.
  endpoint: 'maxrest/rest/os/mxinventory',
  query: {
    ITEMNUM: $.data.itemNum,
    _format: 'json',
  },
  // The JSON response is POSTed here (e.g. a workflow's webhook URL).
  postUrl: $.configuration.webhookUrl,
});

Fetch Open Work Orders.code:
// Get approved work orders for a site and forward them.
fetch({
  endpoint: 'maxrest/rest/mbo/workorder',
  query: {
    STATUS: 'APPR',
    SITEID: $.data.siteId,
    _format: 'json',
    _maxItems: 100,
  },
  postUrl: $.configuration.webhookUrl,
});

Fetch Assets.code:
// Get assets at a location and forward them.
fetch({
  endpoint: 'maxrest/rest/mbo/asset',
  query: {
    LOCATION: $.data.location,
    _format: 'json',
    _compact: 1,
  },
  postUrl: $.configuration.webhookUrl,
});
